set-variable.value:
@{
      if (context.Request.Method != "POST") { return "not_applicable"; }
      var body = context.Request.Body.As<JObject>(preserveContent: true);
      return body.Value<string>("method") ?? "not_present";
    }

@{
      if (context.Request.Method != "POST") { return "not_applicable"; }
      var body = context.Request.Body.As<JObject>(preserveContent: true);
      return (string)body.SelectToken("params.name") ?? "not_applicable";
    }

metadata.value:
@{
        var token = (Jwt)context.Variables["toolbox-caller"];
        var selected = new JObject();
        foreach (var name in new [] { "iss", "aud", "tid", "oid", "azp", "appid", "scp", "roles", "idtyp", "ver", "exp", "iat" }) {
          if (token.Claims.ContainsKey(name)) {
            var values = token.Claims[name];
            selected[name] = name == "roles" || values.Length != 1 ? (JToken)new JArray(values) : (JToken)new JValue(values[0]);
          }
        }
        selected["iss"] = token.Issuer;
        selected["aud"] = new JArray(token.Audiences);
        return selected.ToString(Newtonsoft.Json.Formatting.None);
      }

@{
        var authorization = context.Request.Headers.GetValueOrDefault("Authorization", "");
        var token = authorization.Substring(authorization.IndexOf(' ') + 1);
        var segment = token.Split('.')[0].Replace('-', '+').Replace('_', '/');
        segment = segment.PadRight(segment.Length + (4 - segment.Length % 4) % 4, '=');
        var header = JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(segment)));
        var selected = new JObject();
        foreach (var name in new [] { "alg", "kid" }) {
          if (header[name] != null) { selected[name] = header[name]; }
        }
        return selected.ToString(Newtonsoft.Json.Formatting.None);
      }
